import{_ as t,C as n,o as s,c as r,a9 as a,E as i}from"./chunks/framework.asyjyako.js";const f=JSON.parse('{"title":"Suites and comparisons","description":"","frontmatter":{},"headers":[],"relativePath":"suites-and-comparisons.md","filePath":"suites-and-comparisons.md","lastUpdated":null}'),l={name:"suites-and-comparisons.md"};function p(d,e,c,h,m,u){const o=n("DocMedia");return s(),r("div",null,[e[0]||(e[0]=a('<h1 id="Suites-and-comparisons" tabindex="-1">Suites and comparisons <a class="header-anchor" href="#Suites-and-comparisons" aria-label="Permalink to &quot;Suites and comparisons {#Suites-and-comparisons}&quot;">​</a></h1><ul><li><p>A <strong>workload</strong> is one operation with its inputs.</p></li><li><p>A <strong>suite</strong> groups workloads with the package versions and tools needed to repeat them.</p></li><li><p>A <strong>plan</strong> lists the individual measurements before any worker starts.</p></li><li><p>A <strong>run</strong> is the saved result of executing a plan.</p></li><li><p>A <strong>comparison</strong> is the change from a chosen reference, with optional pass/fail limits.</p></li></ul><h2 id="A-concrete-example" tabindex="-1">A concrete example <a class="header-anchor" href="#A-concrete-example" aria-label="Permalink to &quot;A concrete example {#A-concrete-example}&quot;">​</a></h2><p>To see how BibTeX export changed between Bibliography 0.1.0 and 0.4.0:</p><ul><li><p><strong>Workload</strong> — export the same prepared bibliography.</p></li><li><p><strong>Implementations</strong> — nine tagged versions.</p></li><li><p><strong>Measurements</strong> — elapsed time and allocated bytes.</p></li><li><p><strong>Settings</strong> — one worker thread, 100 samples per version.</p></li></ul><p>Inspect a plan before running it. The plan lists rows and marks unsupported combinations <code>unavailable</code> with a reason.</p><p>Run one of these before measuring:</p><ul><li><p>Existing <code>@testitem</code> — <a href="./guide/first-check">Quickstart</a>. Setup and assertions are part of the cost.</p></li><li><p>One operation — inline <code>@check</code>, with preparation outside the measured expression. See the <a href="./reference/api">Julia API</a>.</p></li><li><p>Several workloads, versions or collectors — <a href="./software-suites">Define a suite</a>.</p></li></ul><h2 id="Interfaces-do-not-change-meaning" tabindex="-1">Interfaces do not change meaning <a class="header-anchor" href="#Interfaces-do-not-change-meaning" aria-label="Permalink to &quot;Interfaces do not change meaning {#Interfaces-do-not-change-meaning}&quot;">​</a></h2><p>The Julia API, VS Code, Oxygen and Pluto select what to run and read the same saved results. Makie renders them. Choose an interface for convenience, not for a different measurement.</p><h2 id="Recorded-examples" tabindex="-1">Recorded examples <a class="header-anchor" href="#Recorded-examples" aria-label="Permalink to &quot;Recorded examples {#Recorded-examples}&quot;">​</a></h2>',11)),i(o,{src:"/examples/bibliography/figures/history-time.svg",alt:"Bibliography export timing across nine tagged versions, from 0.1.0 to 0.4.0",caption:"Actual recorded measurements: 100 samples per version, Windows, Julia 1.13.0, one worker thread. Each point is a median; lower means less elapsed time."}),e[1]||(e[1]=a('<h2 id="Next" tabindex="-1">Next <a class="header-anchor" href="#Next" aria-label="Permalink to &quot;Next {#Next}&quot;">​</a></h2><p><a href="./software-suites">Define a suite</a> and add a candidate revision to compare. <a id="A-concrete-example:-Bibliography"></a><a id="Start-with-the-code-you-already-have"></a><a id="Follow-one-experiment-through-the-interfaces"></a><a id="Continue-from-here"></a></p>',2))])}const x=t(l,[["render",p]]);export{f as __pageData,x as default};
